// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes the row with the fields its behaviors own as the
// core's create gives them (D103), and the update sets update's own fields
// alone; an update that sets no field leaves the row as it is.
func (r *ShipmentRepository) UpsertOne(ctx context.Context, input *ShipmentCreate, on ShipmentUniqueKey, update *ShipmentUpdate) (*types.Shipment, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. It
// runs in a transaction of its own when none is open: the core's create of
// the row comes first, in it (D103).
func (r *ShipmentRepository) UpsertOneResult(ctx context.Context, input *ShipmentCreate, on ShipmentUniqueKey, update *ShipmentUpdate, opts *UpsertOptions) (UpsertResult[*types.Shipment], error) {
	var none UpsertResult[*types.Shipment]
	key, ok := shipmentUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: Shipment has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "Shipment", string(on))
	}
	if update == nil {
		update = &ShipmentUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.Shipment], error) {
		repo := &ShipmentRepository{tx: tx, txDB: r.database()}
		rows, err := repo.upsertInputs(ctx, []*ShipmentCreate{input})
		if err != nil {
			return none, err
		}
		result, err := repo.upsertRow(ctx, rows[0], on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	})
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
// statement of an encrypted field.
